// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title IAntiGravityToken
 * @notice Interface for the AntiGravityToken contract used by the Anchor.
 */
interface IAntiGravityToken {
    function mint(address to, uint256 amount) external;
}

/**
 * @title AntiGravityAnchor
 * @author AntiGravity Team
 * @notice Core contract for anchoring digital twin Merkle roots on-chain,
 *         managing dark periods during infrastructure attacks, and recording
 *         tamper evidence. Rewards agents with AGVT tokens for contributions.
 * @dev Agents submit Merkle roots every ~60 seconds to create an immutable
 *      audit trail. During dark periods (infrastructure attacks), agents can
 *      submit tamper evidence comparing pre-attack and post-attack states.
 */
contract AntiGravityAnchor is Ownable, ReentrancyGuard {
    // ──────────────────────────────────────────────
    //  Types
    // ──────────────────────────────────────────────

    /// @notice Represents a single Merkle root anchor submission
    struct MerkleAnchor {
        bytes32 root;
        string ipfsCID;
        uint256 timestamp;
        address submitter;
        uint256 blockNumber;
    }

    /// @notice Represents a dark period (infrastructure attack window)
    struct DarkPeriod {
        uint256 startTime;
        uint256 endTime;
        string forensicReportCID;
        bool active;
        address declaredBy;
    }

    /// @notice Represents on-chain tamper evidence
    struct TamperEvidence {
        bytes32 preAttackRoot;
        bytes32 postAttackRoot;
        string evidenceCID;
        address submitter;
        uint256 timestamp;
    }

    /// @notice Tracks cumulative statistics for each agent
    struct AgentStats {
        uint256 totalAnchors;
        uint256 totalRewards;
    }

    // ──────────────────────────────────────────────
    //  State Variables
    // ──────────────────────────────────────────────

    /// @notice Reference to the AGVT token contract
    IAntiGravityToken public immutable agvtToken;

    /// @notice Reward for submitting a Merkle root anchor (100 AGVT)
    uint256 public constant ANCHOR_REWARD = 100 * 1e18;

    /// @notice Reward for submitting tamper evidence (1000 AGVT)
    uint256 public constant TAMPER_REWARD = 1000 * 1e18;

    /// @notice Ordered list of all Merkle root submissions
    MerkleAnchor[] public merkleHistory;

    /// @notice Ordered list of all dark periods
    DarkPeriod[] public darkPeriods;

    /// @notice Ordered list of all tamper evidence submissions
    TamperEvidence[] public tamperEvidences;

    /// @notice Per-agent cumulative stats
    mapping(address => AgentStats) public agentStats;

    /// @notice Addresses authorized to declare dark periods (in addition to owner)
    mapping(address => bool) public authorizedAgents;

    // ──────────────────────────────────────────────
    //  Events
    // ──────────────────────────────────────────────

    /// @dev Emitted when a new Merkle root is anchored
    event RootAnchored(
        bytes32 indexed root,
        string ipfsCID,
        uint256 timestamp,
        address indexed submitter,
        uint256 indexed anchorIndex
    );

    /// @dev Emitted when a dark period is declared
    event DarkPeriodStarted(uint256 indexed darkPeriodId, uint256 startTime, address indexed declaredBy);

    /// @dev Emitted when a dark period ends
    event DarkPeriodEnded(uint256 indexed darkPeriodId, uint256 endTime, string reportCID);

    /// @dev Emitted when tamper evidence is submitted
    event TamperDetected(
        bytes32 indexed preAttackRoot,
        bytes32 indexed postAttackRoot,
        string evidenceCID,
        address indexed submitter,
        uint256 evidenceIndex
    );

    /// @dev Emitted when an agent is authorized or deauthorized
    event AgentAuthorizationUpdated(address indexed agent, bool authorized);

    // ──────────────────────────────────────────────
    //  Errors
    // ──────────────────────────────────────────────

    /// @dev Thrown when a non-authorized caller tries to declare a dark period
    error NotAuthorized();

    /// @dev Thrown when trying to declare a dark period while one is already active
    error DarkPeriodAlreadyActive();

    /// @dev Thrown when trying to end a dark period when none is active
    error NoDarkPeriodActive();

    /// @dev Thrown when the requested count exceeds available history
    error InsufficientHistory();

    /// @dev Thrown when an empty IPFS CID is provided
    error EmptyIPFSCID();

    /// @dev Thrown when pre and post attack roots are identical
    error RootsMustDiffer();

    // ──────────────────────────────────────────────
    //  Constructor
    // ──────────────────────────────────────────────

    /**
     * @notice Deploys the AntiGravityAnchor contract.
     * @param _tokenAddress The address of the deployed AntiGravityToken contract
     */
    constructor(address _tokenAddress) Ownable(msg.sender) {
        agvtToken = IAntiGravityToken(_tokenAddress);
    }

    // ──────────────────────────────────────────────
    //  Agent Authorization
    // ──────────────────────────────────────────────

    /**
     * @notice Authorizes or deauthorizes an agent to declare dark periods.
     * @dev Only callable by the contract owner.
     * @param agent The address to authorize or deauthorize
     * @param authorized Whether the agent should be authorized
     */
    function setAgentAuthorization(address agent, bool authorized) external onlyOwner {
        authorizedAgents[agent] = authorized;
        emit AgentAuthorizationUpdated(agent, authorized);
    }

    // ──────────────────────────────────────────────
    //  Core Functions
    // ──────────────────────────────────────────────

    /**
     * @notice Submits a Merkle root anchoring the current state of a digital twin.
     * @dev Anyone can submit. The submitter is rewarded with 100 AGVT tokens.
     *      This creates an immutable on-chain record that can be used to detect
     *      tampering during dark periods.
     * @param root The Merkle root hash of the digital twin state
     * @param ipfsCID The IPFS content identifier pointing to the full state data
     * @param timestamp The off-chain timestamp when the state snapshot was taken
     */
    function submitMerkleRoot(
        bytes32 root,
        string calldata ipfsCID,
        uint256 timestamp
    ) external nonReentrant {
        if (bytes(ipfsCID).length == 0) revert EmptyIPFSCID();

        uint256 anchorIndex = merkleHistory.length;

        merkleHistory.push(
            MerkleAnchor({
                root: root,
                ipfsCID: ipfsCID,
                timestamp: timestamp,
                submitter: msg.sender,
                blockNumber: block.number
            })
        );

        agentStats[msg.sender].totalAnchors += 1;
        agentStats[msg.sender].totalRewards += ANCHOR_REWARD;

        agvtToken.mint(msg.sender, ANCHOR_REWARD);

        emit RootAnchored(root, ipfsCID, timestamp, msg.sender, anchorIndex);
    }

    /**
     * @notice Declares the start of a dark period (infrastructure attack detected).
     * @dev Only callable by the contract owner or an authorized agent.
     *      Only one dark period can be active at a time.
     */
    function declareDarkPeriod() external nonReentrant {
        if (msg.sender != owner() && !authorizedAgents[msg.sender]) revert NotAuthorized();

        // Check no active dark period
        uint256 periodCount = darkPeriods.length;
        if (periodCount > 0 && darkPeriods[periodCount - 1].active) {
            revert DarkPeriodAlreadyActive();
        }

        uint256 darkPeriodId = periodCount;

        darkPeriods.push(
            DarkPeriod({
                startTime: block.timestamp,
                endTime: 0,
                forensicReportCID: "",
                active: true,
                declaredBy: msg.sender
            })
        );

        emit DarkPeriodStarted(darkPeriodId, block.timestamp, msg.sender);
    }

    /**
     * @notice Ends the currently active dark period and stores the forensic report.
     * @dev Only callable by the contract owner or an authorized agent.
     *      Requires an active dark period to exist.
     * @param forensicReportCID The IPFS CID of the AI-generated forensic report
     */
    function endDarkPeriod(string calldata forensicReportCID) external nonReentrant {
        if (msg.sender != owner() && !authorizedAgents[msg.sender]) revert NotAuthorized();
        if (bytes(forensicReportCID).length == 0) revert EmptyIPFSCID();

        uint256 periodCount = darkPeriods.length;
        if (periodCount == 0 || !darkPeriods[periodCount - 1].active) {
            revert NoDarkPeriodActive();
        }

        uint256 darkPeriodId = periodCount - 1;
        DarkPeriod storage period = darkPeriods[darkPeriodId];
        period.endTime = block.timestamp;
        period.forensicReportCID = forensicReportCID;
        period.active = false;

        emit DarkPeriodEnded(darkPeriodId, block.timestamp, forensicReportCID);
    }

    /**
     * @notice Submits tamper evidence comparing pre-attack and post-attack states.
     * @dev Anyone can submit evidence. The submitter is rewarded with 1000 AGVT tokens.
     *      Pre and post-attack roots must be different to constitute evidence of tampering.
     * @param preAttackRoot The Merkle root of the digital twin state before the attack
     * @param postAttackRoot The Merkle root of the digital twin state after the attack
     * @param evidenceCID The IPFS CID pointing to the detailed tamper evidence data
     */
    function submitTamperEvidence(
        bytes32 preAttackRoot,
        bytes32 postAttackRoot,
        string calldata evidenceCID
    ) external nonReentrant {
        if (preAttackRoot == postAttackRoot) revert RootsMustDiffer();
        if (bytes(evidenceCID).length == 0) revert EmptyIPFSCID();

        uint256 evidenceIndex = tamperEvidences.length;

        tamperEvidences.push(
            TamperEvidence({
                preAttackRoot: preAttackRoot,
                postAttackRoot: postAttackRoot,
                evidenceCID: evidenceCID,
                submitter: msg.sender,
                timestamp: block.timestamp
            })
        );

        agentStats[msg.sender].totalRewards += TAMPER_REWARD;

        agvtToken.mint(msg.sender, TAMPER_REWARD);

        emit TamperDetected(preAttackRoot, postAttackRoot, evidenceCID, msg.sender, evidenceIndex);
    }

    // ──────────────────────────────────────────────
    //  View Functions
    // ──────────────────────────────────────────────

    /**
     * @notice Returns the last N Merkle root anchors from the history.
     * @dev If count exceeds the total history length, all records are returned.
     * @param count The number of recent anchors to retrieve
     * @return anchors Array of MerkleAnchor structs
     */
    function getMerkleHistory(uint256 count) external view returns (MerkleAnchor[] memory anchors) {
        uint256 total = merkleHistory.length;
        uint256 returnCount = count > total ? total : count;

        anchors = new MerkleAnchor[](returnCount);
        uint256 startIndex = total - returnCount;

        for (uint256 i = 0; i < returnCount; i++) {
            anchors[i] = merkleHistory[startIndex + i];
        }
    }

    /**
     * @notice Returns cumulative statistics for a given agent.
     * @param agent The address of the agent to query
     * @return totalAnchors The total number of Merkle roots submitted by the agent
     * @return totalRewards The total AGVT tokens earned by the agent
     */
    function getAgentStats(address agent)
        external
        view
        returns (uint256 totalAnchors, uint256 totalRewards)
    {
        AgentStats storage stats = agentStats[agent];
        return (stats.totalAnchors, stats.totalRewards);
    }

    /**
     * @notice Returns the total number of anchored Merkle roots.
     * @return count The length of the merkleHistory array
     */
    function getMerkleCount() external view returns (uint256 count) {
        return merkleHistory.length;
    }

    /**
     * @notice Returns the total number of dark periods (active and ended).
     * @return count The length of the darkPeriods array
     */
    function getDarkPeriodCount() external view returns (uint256 count) {
        return darkPeriods.length;
    }

    /**
     * @notice Returns the total number of tamper evidence submissions.
     * @return count The length of the tamperEvidences array
     */
    function getTamperEvidenceCount() external view returns (uint256 count) {
        return tamperEvidences.length;
    }
}

contracts/AntiGravityForensics.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title AntiGravityForensics
 * @author AntiGravity Team
 * @notice Stores AI-generated forensic reports for dark period events in the
 *         AntiGravity ecosystem. Provides an immutable on-chain record of
 *         every forensic analysis performed by the Gemini AI forensics engine.
 * @dev Each forensic report is linked to a dark period ID from the
 *      AntiGravityAnchor contract and stores pre/post attack Merkle roots,
 *      tamper detection results, confidence scores, and IPFS report CIDs.
 */
contract AntiGravityForensics is Ownable, ReentrancyGuard {
    // ──────────────────────────────────────────────
    //  Types
    // ──────────────────────────────────────────────

    /// @notice Represents a complete AI forensic report for a dark period
    struct ForensicReport {
        uint256 darkPeriodId;
        string geminiReportCID;
        bytes32 preRoot;
        bytes32 postRoot;
        bool tamperDetected;
        uint256 confidenceScore;
        address filedBy;
        uint256 timestamp;
        bool exists;
    }

    // ──────────────────────────────────────────────
    //  State Variables
    // ──────────────────────────────────────────────

    /// @notice Address of the AntiGravityAnchor contract
    address public immutable anchorContract;

    /// @notice Maps dark period IDs to their forensic reports
    mapping(uint256 => ForensicReport) public forensicReports;

    /// @notice Total number of forensic reports filed
    uint256 public totalReports;

    /// @notice Total number of tampering events detected across all reports
    uint256 public tamperCount;

    /// @notice Array of all dark period IDs that have reports (for enumeration)
    uint256[] private _reportedPeriods;

    // ──────────────────────────────────────────────
    //  Events
    // ──────────────────────────────────────────────

    /// @dev Emitted when a new forensic report is filed
    event ForensicReportFiled(
        uint256 indexed darkPeriodId,
        string geminiReportCID,
        bytes32 indexed preRoot,
        bytes32 indexed postRoot,
        bool tamperDetected,
        uint256 confidenceScore,
        address filedBy
    );

    // ──────────────────────────────────────────────
    //  Errors
    // ──────────────────────────────────────────────

    /// @dev Thrown when a non-authorized caller tries to file a report
    error NotAuthorized();

    /// @dev Thrown when a report already exists for a given dark period
    error ReportAlreadyExists();

    /// @dev Thrown when no report exists for a queried dark period
    error ReportNotFound();

    /// @dev Thrown when an empty report CID is provided
    error EmptyReportCID();

    /// @dev Thrown when the confidence score exceeds 100
    error InvalidConfidenceScore();

    // ──────────────────────────────────────────────
    //  Constructor
    // ──────────────────────────────────────────────

    /**
     * @notice Deploys the AntiGravityForensics contract.
     * @param _anchorContract The address of the deployed AntiGravityAnchor contract
     */
    constructor(address _anchorContract) Ownable(msg.sender) {
        anchorContract = _anchorContract;
    }

    // ──────────────────────────────────────────────
    //  Core Functions
    // ──────────────────────────────────────────────

    /**
     * @notice Records a new AI forensic report for a specific dark period.
     * @dev Only callable by the contract owner or the AntiGravityAnchor contract.
     *      Each dark period can only have one forensic report.
     *      Confidence score must be between 0 and 100 (inclusive).
     * @param darkPeriodId The ID of the dark period this report covers
     * @param geminiReportCID The IPFS CID of the full Gemini AI forensic report
     * @param preRoot The Merkle root of the digital twin state before the attack
     * @param postRoot The Merkle root of the digital twin state after the attack
     * @param tamperDetected Whether the AI detected tampering during analysis
     * @param confidenceScore The AI's confidence in its analysis (0-100)
     */
    function recordForensicReport(
        uint256 darkPeriodId,
        string calldata geminiReportCID,
        bytes32 preRoot,
        bytes32 postRoot,
        bool tamperDetected,
        uint256 confidenceScore
    ) external nonReentrant {
        if (msg.sender != owner() && msg.sender != anchorContract) revert NotAuthorized();
        if (forensicReports[darkPeriodId].exists) revert ReportAlreadyExists();
        if (bytes(geminiReportCID).length == 0) revert EmptyReportCID();
        if (confidenceScore > 100) revert InvalidConfidenceScore();

        forensicReports[darkPeriodId] = ForensicReport({
            darkPeriodId: darkPeriodId,
            geminiReportCID: geminiReportCID,
            preRoot: preRoot,
            postRoot: postRoot,
            tamperDetected: tamperDetected,
            confidenceScore: confidenceScore,
            filedBy: msg.sender,
            timestamp: block.timestamp,
            exists: true
        });

        totalReports += 1;
        _reportedPeriods.push(darkPeriodId);

        if (tamperDetected) {
            tamperCount += 1;
        }

        emit ForensicReportFiled(
            darkPeriodId,
            geminiReportCID,
            preRoot,
            postRoot,
            tamperDetected,
            confidenceScore,
            msg.sender
        );
    }

    // ──────────────────────────────────────────────
    //  View Functions
    // ──────────────────────────────────────────────

    /**
     * @notice Retrieves the full forensic report for a given dark period.
     * @param darkPeriodId The ID of the dark period to query
     * @return report The complete ForensicReport struct
     */
    function getReport(uint256 darkPeriodId) external view returns (ForensicReport memory report) {
        if (!forensicReports[darkPeriodId].exists) revert ReportNotFound();
        return forensicReports[darkPeriodId];
    }

    /**
     * @notice Returns the total number of tampering events detected across all reports.
     * @return count The cumulative tamper count
     */
    function getTamperCount() external view returns (uint256 count) {
        return tamperCount;
    }

    /**
     * @notice Returns all dark period IDs that have forensic reports filed.
     * @return periodIds Array of dark period IDs with reports
     */
    function getReportedPeriods() external view returns (uint256[] memory periodIds) {
        return _reportedPeriods;
    }

    /**
     * @notice Returns the total number of forensic reports filed.
     * @return count The total report count
     */
    function getTotalReports() external view returns (uint256 count) {
        return totalReports;
    }
}

contracts/AntiGravityToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title AntiGravityToken (AGVT)
 * @author AntiGravity Team
 * @notice ERC-20 reward token for the AntiGravity dark-period forensics platform.
 * @dev Minting is restricted to the designated AntiGravityAnchor contract.
 *      Agents earn AGVT by anchoring Merkle roots and submitting tamper evidence.
 *      Agents are ranked by cumulative token earnings into four tiers:
 *      GHOST → PHANTOM → WRAITH → SPECTER.
 */
contract AntiGravityToken is ERC20, Ownable, ReentrancyGuard {
    /// @notice Address of the AntiGravityAnchor contract authorized to mint tokens
    address public minter;

    /// @notice Tracks cumulative AGVT earned (minted) per agent for rank calculation
    mapping(address => uint256) public agentEarnings;

    /// @notice Array of all agents who have ever earned tokens (for leaderboard)
    address[] private _agents;

    /// @notice Tracks whether an address has been added to the _agents array
    mapping(address => bool) private _isRegisteredAgent;

    /// @dev Emitted when the minter address is updated
    event MinterUpdated(address indexed previousMinter, address indexed newMinter);

    /// @dev Emitted when tokens are minted to an agent
    event TokensMinted(address indexed agent, uint256 amount);

    /// @dev Thrown when a non-minter address attempts to mint
    error OnlyMinterCanMint();

    /// @dev Thrown when the minter address is set to the zero address
    error MinterCannotBeZeroAddress();

    /**
     * @notice Deploys the AntiGravityToken contract.
     * @dev Sets the token name to "AntiGravity Token" and symbol to "AGVT".
     *      The deployer becomes the initial owner via Ownable.
     */
    constructor() ERC20("AntiGravity Token", "AGVT") Ownable(msg.sender) {}

    /**
     * @notice Sets the authorized minter address (AntiGravityAnchor contract).
     * @dev Only callable by the contract owner. This should be called once after
     *      deploying the AntiGravityAnchor contract.
     * @param _minter The address of the AntiGravityAnchor contract
     */
    function setMinter(address _minter) external onlyOwner {
        if (_minter == address(0)) revert MinterCannotBeZeroAddress();
        address previousMinter = minter;
        minter = _minter;
        emit MinterUpdated(previousMinter, _minter);
    }

    /**
     * @notice Mints AGVT tokens to a specified agent as a reward.
     * @dev Only callable by the authorized minter (AntiGravityAnchor contract).
     *      Updates cumulative earnings for rank tracking and registers new agents.
     * @param to The address of the agent receiving the reward
     * @param amount The number of tokens to mint (in wei, 18 decimals)
     */
    function mint(address to, uint256 amount) external nonReentrant {
        if (msg.sender != minter) revert OnlyMinterCanMint();

        if (!_isRegisteredAgent[to]) {
            _agents.push(to);
            _isRegisteredAgent[to] = true;
        }

        agentEarnings[to] += amount;
        _mint(to, amount);

        emit TokensMinted(to, amount);
    }

    /**
     * @notice Returns the rank title for a given agent based on their cumulative earnings.
     * @dev Rank tiers (in whole tokens, not wei):
     *      - 0–999 AGVT      → "GHOST"
     *      - 1,000–4,999 AGVT → "PHANTOM"
     *      - 5,000–19,999 AGVT → "WRAITH"
     *      - 20,000+ AGVT     → "SPECTER"
     * @param agent The address of the agent to query
     * @return rank The string rank title of the agent
     */
    function getAgentRank(address agent) external view returns (string memory rank) {
        uint256 tokens = agentEarnings[agent] / 1e18;

        if (tokens >= 20000) {
            return "SPECTER";
        } else if (tokens >= 5000) {
            return "WRAITH";
        } else if (tokens >= 1000) {
            return "PHANTOM";
        } else {
            return "GHOST";
        }
    }

    /**
     * @notice Returns the top 10 agents ranked by current token balance.
     * @dev Iterates all registered agents and maintains a sorted top-10 list.
     *      If fewer than 10 agents exist, returns all of them.
     *      Gas cost scales linearly with total agent count — intended for off-chain reads.
     * @return topAgents Array of addresses (up to 10) sorted by descending balance
     * @return balances Corresponding balances for each agent in topAgents
     */
    function getLeaderboard()
        external
        view
        returns (address[] memory topAgents, uint256[] memory balances)
    {
        uint256 agentCount = _agents.length;
        uint256 leaderboardSize = agentCount < 10 ? agentCount : 10;

        topAgents = new address[](leaderboardSize);
        balances = new uint256[](leaderboardSize);

        // Temporary arrays for sorting
        address[] memory tempAddresses = new address[](leaderboardSize);
        uint256[] memory tempBalances = new uint256[](leaderboardSize);

        for (uint256 i = 0; i < agentCount; i++) {
            address agent = _agents[i];
            uint256 bal = balanceOf(agent);

            // Find position in the sorted top-N list
            uint256 insertPos = leaderboardSize;
            for (uint256 j = 0; j < leaderboardSize; j++) {
                if (bal > tempBalances[j]) {
                    insertPos = j;
                    break;
                }
            }

            // If the agent qualifies for the leaderboard, insert and shift
            if (insertPos < leaderboardSize) {
                for (uint256 k = leaderboardSize - 1; k > insertPos; k--) {
                    tempAddresses[k] = tempAddresses[k - 1];
                    tempBalances[k] = tempBalances[k - 1];
                }
                tempAddresses[insertPos] = agent;
                tempBalances[insertPos] = bal;
            }
        }

        topAgents = tempAddresses;
        balances = tempBalances;
    }

    /**
     * @notice Returns the total number of registered agents.
     * @return count The number of unique addresses that have earned AGVT
     */
    function getAgentCount() external view returns (uint256 count) {
        return _agents.length;
    }
}

